import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { MESSAGING_PRODUCT_NAME, MESSAGING_CONSOLE_URL } from '../../constants/brand';
import { MESSAGING_PLANS, MESSAGING_PRICING_FAQ } from '../../data/messagingPricing';
import '../../styles/marketing.css';

export default function MessagingPricing() {
  return (
    <Layout>
      <SEO
        title={`${MESSAGING_PRODUCT_NAME} pricing — flat, no per-message fees`}
        description={`Four tiers from Free to Ultra, each with unlimited sending. Differences are channel connections, submit rate and log retention. You pay your own provider.`}
        pathname="/messaging/pricing/"
        softwareApp={false}
        faqs={MESSAGING_PRICING_FAQ}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: MESSAGING_PRODUCT_NAME, path: '/messaging/' },
          { name: 'Pricing', path: '/messaging/pricing/' },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">Pricing</span>
          <h1>You pay your provider for messages. You pay us for the layer.</h1>
          <p className="mk-lead">
            Four tiers, monthly or yearly. Every one includes unlimited sending, the full API and no
            overage bills &mdash; because message volume is not something we bill for. What changes
            between tiers is how many connections you can run, how fast you may submit, and how long
            delivery logs are kept.
          </p>
        </header>

        <div className="mk-scope">
          <strong>Why there is no per-message price.</strong> {MESSAGING_PRODUCT_NAME} never sells
          message volume. Your messages are sent on your own provider account, at your own rate, on
          your own invoice. A per-message fee from us would mean we were reselling your provider&rsquo;s
          traffic &mdash; which is exactly the model we are not.
        </div>

        <section className="mk-section">
          <h2>Compare the tiers</h2>
          <div className="mk-price-grid">
            {MESSAGING_PLANS.map((p) => (
              <article className={`mk-price-card${p.highlighted ? ' mk-price-card-hot' : ''}`} key={p.id}>
                {p.highlighted && <span className="mk-card-tag">Most popular</span>}
                <h3>{p.name}</h3>
                <p className="mk-price-amount">{p.monthly}</p>
                <p className="mk-price-note">{p.priceNote}</p>
                <p className="mk-price-for">{p.for}</p>
                <ul className="mk-list">
                  {p.features.map((f) => (
                    <li key={f}>{f}</li>
                  ))}
                </ul>
                <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}>
                  Start on {p.name}
                </a>
              </article>
            ))}
          </div>
          <p className="mk-section-lead">
            Yearly billing is roughly two months cheaper than paying monthly. Prices are in USD;
            taxes may apply by region. Nothing is charged automatically when you reach a limit &mdash;
            you upgrade when you choose to.
          </p>
        </section>

        <section className="mk-section">
          <h2>How the tiers differ</h2>
          <p className="mk-section-lead">
            Tiers differ in three dimensions. Here is what each one measures, and what happens when
            you reach it &mdash; so there are no surprises on the invoice.
          </p>
          <table className="mk-table">
            <thead>
              <tr>
                <th>Dimension</th>
                <th>What it measures</th>
                <th>What happens at the limit</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Channel connections</td>
                <td>How many configured provider connections you hold at once</td>
                <td>Add another only after upgrading or removing one</td>
              </tr>
              <tr>
                <td>Submit rate (QPS)</td>
                <td>How fast you may hand messages to the platform</td>
                <td>Requests are paced rather than rejected outright</td>
              </tr>
              <tr>
                <td>Log retention</td>
                <td>How long delivery metadata stays queryable</td>
                <td>Older records age out; sending is unaffected</td>
              </tr>
            </tbody>
          </table>
          <div className="mk-scope">
            <strong>Submit rate vs send pace.</strong> The submit rate is how fast <em>you</em> may
            give us messages. The send pace is how fast <em>we</em> call your provider on a given
            connection &mdash; and it is set by that provider&rsquo;s quota, not by your plan. The
            lower of the two governs.
          </div>
        </section>

        <section className="mk-section">
          <h2>Pricing questions</h2>
          <dl className="mk-faq">
            {MESSAGING_PRICING_FAQ.map((f) => (
              <div key={f.q}>
                <dt>{f.q}</dt>
                <dd>{f.a}</dd>
              </div>
            ))}
          </dl>
        </section>

        <section className="mk-section">
          <h2>Still deciding?</h2>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to="/integrations/">
              See which providers you can connect
            </Link>
            <Link className="mk-btn mk-btn-secondary" to="/faq/">
              Read the FAQ
            </Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
